async ({ git: { add, commit, push, status } }) => {
  await add(["-A"]);
  const st = await status(["--short"]);
  const c = await commit(["-m", "feat: load skills (SKILL.md), list them in the system prompt, and expand /skill:<name>", "-m", "Discover skills in packages (extensions, and the new skills input), the project's .pi/skills and .agents/skills (trust_project only), and <agent_dir>/skills. A built-in pi-durable extension, pi-action, lists them in an available_skills section, and /skill:<name> puts a skill's SKILL.md in the request; an unknown name gets an error reply.\n\nCloses #54"]);
  const p = await push(["-u", "origin", "feat/skills"]);
  return { st: st.stdout, c: c.stdout + c.stderr, p: p.stdout + p.stderr };
}
